#include <stdio.h>

#define MAXN 100005

static int a[MAXN];
static int tmp[MAXN];
static long long inv_count = 0;

/* 合并 [left, mid] 与 [mid + 1, right] 两个有序段，并累加跨段的逆序对 */
void merge_range(int left, int mid, int right)
{
    int i = left, j = mid + 1, k = left;

    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
            inv_count += mid - i + 1;   /* 左段剩下的都比 a[j] 大 */
        }
    }
    while (i <= mid)
        tmp[k++] = a[i++];
    while (j <= right)
        tmp[k++] = a[j++];
    for (i = left; i <= right; i++)
        a[i] = tmp[i];
}

/* 递归分治：把区间一分为二，各自排好序后再合并 */
void merge_sort(int left, int right)
{
    int mid;

    if (left >= right)
        return;
    mid = left + (right - left) / 2;
    merge_sort(left, mid);
    merge_sort(mid + 1, right);
    merge_range(left, mid, right);
}

int main(void)
{
    int n, i;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }
    merge_sort(0, n - 1);
    for (i = 0; i < n; i++) {
        if (i > 0)
            putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
    printf("%lld\n", inv_count);
    return 0;
}

