/* 递归快速幂：返回 a^n mod m */
long long pow_mod(long long a, long long n, long long m)
{
    long long half;

    if (m == 1)
        return 0;
    if (n == 0)
        return 1;
    half = pow_mod(a, n / 2, m);
    half = half * half % m;          /* 先算 a^(n/2)，再平方 */
    if (n % 2 == 1)
        half = half * a % m;         /* 指数为奇数时再补乘一个 a */
    return half;
}

int main(void)
{
    long long a, n, m;

    if (scanf("%lld %lld %lld", &a, &n, &m) != 3)
        return 0;
    printf("%lld\n", pow_mod(a % m, n, m));
    return 0;
}

