#include <stdio.h>
#include <string.h>

/* 只保留字母与数字，字母统一转成小写 */
void clean_text(const char *src, char *dst)
{
    int i, k = 0;

    for (i = 0; src[i] != '\0'; i++) {
        char ch = src[i];
        if (ch >= 'A' && ch <= 'Z')
            dst[k++] = (char)(ch - 'A' + 'a');
        else if ((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9'))
            dst[k++] = ch;
    }
    dst[k] = '\0';
}

/* 判断 s 是否回文：是返回 1，否返回 0 */
int is_palindrome(const char *s)
{
    int i = 0;
    int j = (int)strlen(s) - 1;

    while (i < j) {
        if (s[i] != s[j])
            return 0;
        i++;
        j--;
    }
    return 1;
}

/* 统计原始文本中字母、数字与其他字符（含空格）的个数 */
void count_chars(const char *s, int *letters, int *digits, int *others)
{
    int i;

    *letters = 0;
    *digits = 0;
    *others = 0;
    for (i = 0; s[i] != '\0'; i++) {
        char ch = s[i];
        if ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z'))
            (*letters)++;
        else if (ch >= '0' && ch <= '9')
            (*digits)++;
        else
            (*others)++;
    }
}

/* 输出单独抽成一个函数，主函数里不再出现 printf */
void print_report(const char *clean, int palindrome,
                  int letters, int digits, int others)
{
    printf("clean = %s\n", clean);
    printf("palindrome = %s\n", palindrome ? "yes" : "no");
    printf("letters = %d digits = %d others = %d\n", letters, digits, others);
}

int main(void)
{
    char line[512];
    char clean[512];
    int letters, digits, others;
    size_t len;

    if (fgets(line, (int)sizeof line, stdin) == NULL)
        return 0;
    len = strlen(line);
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
        line[--len] = '\0';

    clean_text(line, clean);
    count_chars(line, &letters, &digits, &others);
    print_report(clean, is_palindrome(clean), letters, digits, others);
    return 0;
}

