import sys


def clean_text(src):
    """只保留字母与数字，字母统一转成小写。"""
    out = []
    for ch in src:
        if "A" <= ch <= "Z":
            out.append(ch.lower())
        elif "a" <= ch <= "z" or "0" <= ch <= "9":
            out.append(ch)
    return "".join(out)


def is_palindrome(s):
    """正读反读相同返回 True。"""
    return s == s[::-1]


def count_chars(s):
    """统计原始文本中字母、数字与其他字符（含空格）的个数。"""
    letters = digits = others = 0
    for ch in s:
        if "A" <= ch <= "Z" or "a" <= ch <= "z":
            letters += 1
        elif "0" <= ch <= "9":
            digits += 1
        else:
            others += 1
    return letters, digits, others


def print_report(clean, palindrome, letters, digits, others):
    print(f"clean = {clean}")
    print(f"palindrome = {'yes' if palindrome else 'no'}")
    print(f"letters = {letters} digits = {digits} others = {others}")


def main():
    line = sys.stdin.readline()
    if line == "":
        return
    line = line.rstrip("\r\n")

    clean = clean_text(line)
    letters, digits, others = count_chars(line)
    print_report(clean, is_palindrome(clean), letters, digits, others)


if __name__ == "__main__":
    main()

