#include <stdio.h>

static int n;
static int pos[12];              /* pos[row] = 该行皇后所在列 */
static int first_solution[12];
static long long solution_count = 0;

/* 第 row 行第 col 列能否放皇后：只需检查上面已经放好的各行 */
int can_place(int row, int col)
{
    int r;

    for (r = 1; r < row; r++) {
        if (pos[r] == col)                 /* 同列 */
            return 0;
        if (pos[r] - r == col - row)       /* 主对角线 */
            return 0;
        if (pos[r] + r == col + row)       /* 副对角线 */
            return 0;
    }
    return 1;
}

/* 回溯：一行一行往下放 */
void dfs(int row)
{
    int col;

    if (row > n) {
        solution_count++;
        if (solution_count == 1) {
            for (col = 1; col <= n; col++)
                first_solution[col] = pos[col];
        }
        return;
    }
    for (col = 1; col <= n; col++) {
        if (can_place(row, col)) {
            pos[row] = col;
            dfs(row + 1);
        }
    }
}

int main(void)
{
    int i;

    if (scanf("%d", &n) != 1)
        return 0;
    dfs(1);
    printf("%lld\n", solution_count);
    for (i = 1; i <= n; i++) {
        if (i > 1)
            putchar(' ');
        printf("%d", first_solution[i]);
    }
    putchar('\n');
    return 0;
}

