#include <stdio.h>

#define MAXN 100005

static long long a[MAXN];

/* 求跨越中点的最大子段和：左半必须以 mid 结尾，右半必须以 mid + 1 开头 */
long long max_cross(int left, int mid, int right)
{
    long long sum = 0;
    long long best_left = a[mid];
    long long best_right = a[mid + 1];
    int i;

    for (i = mid; i >= left; i--) {
        sum += a[i];
        if (sum > best_left)
            best_left = sum;
    }
    sum = 0;
    for (i = mid + 1; i <= right; i++) {
        sum += a[i];
        if (sum > best_right)
            best_right = sum;
    }
    return best_left + best_right;
}

/* 分治：答案要么在左半、要么在右半、要么跨越中点 */
long long max_sub(int left, int right)
{
    int mid;
    long long best, other;

    if (left == right)
        return a[left];

    mid = left + (right - left) / 2;
    best = max_sub(left, mid);
    other = max_sub(mid + 1, right);
    if (other > best)
        best = other;
    other = max_cross(left, mid, right);
    if (other > best)
        best = other;
    return best;
}

int main(void)
{
    int n, i;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%lld", &a[i]) != 1)
            return 0;
    }
    printf("%lld\n", max_sub(0, n - 1));
    return 0;
}

