    sum = 0;
    for (int i = mid + 1; i <= right; ++i) {
        sum += a[i];
        if (sum > best_right)
            best_right = sum;
    }
    return best_left + best_right;
}

long long max_sub(const std::vector<long long> &a, int left, int right)
{
    if (left == right)
        return a[left];

    int mid = left + (right - left) / 2;
    long long best = max_sub(a, left, mid);
    long long right_best = max_sub(a, mid + 1, right);
    if (right_best > best)
        best = right_best;
    long long cross_best = max_cross(a, left, mid, right);
    if (cross_best > best)
        best = cross_best;
    return best;
}

