#include <stdlib.h>

#define MAXN 100005

static int a[MAXN];

int cmp_asc(const void *p, const void *q)
{
    int x = *(const int *)p;
    int y = *(const int *)q;

    return (x > y) - (x < y);
}

int cmp_desc(const void *p, const void *q)
{
    int x = *(const int *)p;
    int y = *(const int *)q;

    return (x < y) - (x > y);
}

int cmp_abs(const void *p, const void *q)
{
    int x = *(const int *)p;
    int y = *(const int *)q;
    int ax = x < 0 ? -x : x;
    int ay = y < 0 ? -y : y;

    if (ax != ay)                    /* 绝对值不同时按绝对值升序 */
        return (ax > ay) - (ax < ay);
    return (x > y) - (x < y);        /* 绝对值相同则小的在前 */
}

/* 把比较函数作为参数传进来，内部交给 qsort */
void sort_with(int *data, int count, int (*cmp)(const void *, const void *))
{
    qsort(data, (size_t)count, sizeof(int), cmp);
}

int main(void)
{
    int n, op, i;
    int (*cmp)(const void *, const void *);
    static const char *names[] = { "", "ascending", "descending", "absolute" };

    if (scanf("%d %d", &n, &op) != 2)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    if (op == 1)
        cmp = cmp_asc;
    else if (op == 2)
        cmp = cmp_desc;
    else
        cmp = cmp_abs;
    sort_with(a, n, cmp);

    for (i = 0; i < n; i++) {
        if (i > 0)
            putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
    printf("strategy = %s\n", names[op]);
    return 0;
}

