#include <stdio.h>

#define MAXN 25

static int n, target;
static int a[MAXN];
static long long suf[MAXN];       /* suf[i] = a[i] + ... + a[n-1] */
static long long subset_count = 0;

/* 回溯：第 i 个数选或不选，sum 为已经选出的元素之和 */
void dfs(int i, int sum)
{
    if (sum == target) {          /* 达到目标和，且元素都是正数，无需再选 */
        subset_count++;
        return;
    }
    if (i >= n || sum > target)
        return;
    if (sum + suf[i] < target)    /* 后面全选也不够，剪枝 */
        return;

    dfs(i + 1, sum + a[i]);       /* 选第 i 个 */
    dfs(i + 1, sum);              /* 不选第 i 个 */
}

int main(void)
{
    int i;

    if (scanf("%d %d", &n, &target) != 2)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }
    suf[n] = 0;
    for (i = n - 1; i >= 0; i--)
        suf[i] = suf[i + 1] + a[i];

    dfs(0, 0);
    printf("%lld\n", subset_count);
    return 0;
}

